    public static partial class TimingAnalysis {
        static readonly string[] DescriptorFields="calls hit unknown uncacheable layout shape payload layout_only changed_segments comparable_segments changed_infos one few many buffer offset range sampler view image_layout texel_view".Split(' ');
        static readonly string[] UpdateFields="calls full partial skipped input emitted omitted partial_omitted".Split(' ');
        static readonly Regex DescriptorPattern=new Regex(@"Perf R4 descriptors: calls (\d+) hit (\d+) unknown (\d+) uncacheable (\d+) layout (\d+) shape (\d+) payload (\d+) layout-only (\d+); changed segments (\d+)/(\d+) infos (\d+) one/few/many (\d+)/(\d+)/(\d+); fields buffer (\d+) offset (\d+) range (\d+) sampler (\d+) view (\d+) image-layout (\d+) texel-view (\d+)\s*$");
        static readonly Regex UpdatePattern=new Regex(@"Perf A1 descriptors: calls (\d+) full (\d+) partial (\d+) skipped (\d+); write segments input (\d+) emitted (\d+) omitted (\d+) partial-omitted (\d+)\s*$");
        static readonly Regex PreparePattern=new Regex(@"Perf R4 prepare: calls (\d+) ms ([\d.]+); buffers (\d+) ms ([\d.]+); textures (\d+) ms ([\d.]+); regular sets (\d+) writes (\d+)\s*$");
        static Dictionary<string,object> CounterLine(string line,Regex pattern,string[] fields,string error){var match=pattern.Match(line);Check(match.Success,error);var row=M();for(int i=0;i<fields.Length;++i)row[fields[i]]=DiagnosticData.ParseInt(match.Groups[i+1].Value);return row;}
        public static Dictionary<string,object> DescriptorLine(string line){return CounterLine(line,DescriptorPattern,DescriptorFields,"malformed R4 descriptor counters");}
        public static Dictionary<string,object> UpdateLine(string line){return CounterLine(line,UpdatePattern,UpdateFields,"malformed A1 descriptor counters");}
        public static Dictionary<string,object> DescriptorInvariants(Dictionary<string,object> row){return M("calls_minus_reasons",L(row,"calls")-new[]{"hit","unknown","uncacheable","layout","shape","payload"}.Sum(key=>L(row,key)),"layout_only_excess",Math.Max(0,L(row,"layout_only")-L(row,"layout")),"changed_segments_excess",Math.Max(0,L(row,"changed_segments")-L(row,"comparable_segments")),"changed_infos_deficit",Math.Max(0,L(row,"changed_segments")-L(row,"changed_infos")),"distribution_excess",Math.Max(0,new[]{"one","few","many"}.Sum(key=>L(row,key))-L(row,"layout")-L(row,"payload")));}
        public static Dictionary<string,object> UpdateInvariants(Dictionary<string,object> row){return M("calls_minus_modes",L(row,"calls")-L(row,"full")-L(row,"partial")-L(row,"skipped"),"input_minus_emitted_and_omitted",L(row,"input")-L(row,"emitted")-L(row,"omitted"),"partial_omitted_excess",Math.Max(0,L(row,"partial_omitted")-L(row,"omitted")));}
        static bool Zero(Dictionary<string,object> row){return row.Values.All(value=>Convert.ToInt64(value)==0);}
        public static Dictionary<string,object> DepthSpirvFacts(byte[] data){
            Check(data.Length>=20&&data.Length%4==0,"C1 dump has invalid word length");var words=new uint[data.Length/4];Buffer.BlockCopy(data,0,words,0,data.Length);Check(words[0]==0x07230203,"C1 dump has invalid SPIR-V magic");
            var names=new Dictionary<uint,string>{{353,"subgroup_signed_min"},{356,"subgroup_signed_max"},{333,"subgroup_elect"},{236,"shared_signed_min_atomic"},{238,"shared_signed_max_atomic"},{224,"control_barrier"}};var counts=new Dictionary<string,long>();bool arithmetic=false;int at=5;
            while(at<words.Length){int count=(int)(words[at]>>16);uint op=words[at]&65535;Check(count>0&&count<=words.Length-at,"C1 dump has truncated instruction");string name;if(names.TryGetValue(op,out name))DiagnosticData.AddCount(counts,name);if(op==17&&count==2&&words[at+1]==63)arithmetic=true;at+=count;}
            bool observed=arithmetic&&new[]{"subgroup_signed_min","subgroup_signed_max","subgroup_elect","shared_signed_min_atomic","shared_signed_max_atomic"}.All(key=>Count(counts,key)==1);return M("arithmetic_capability",arithmetic,"operations",DiagnosticData.Counts(counts),"candidate_pattern_observed",observed);
        }
        public static Dictionary<string,object> DepthReduction(string session){
            var startup=new List<object>();var compiles=new List<object>();var binaries=new List<object>();var issues=new List<string>();var start=new Regex(@"C1 depth reduction: requested=(true|false) supported=(true|false) active=(true|false)");var compiled=new Regex(@"C1 depth reduction shader 0xce1675e0 permutation (\d+): applied=(true|false) reason=([a-z0-9-]+)");
            try{foreach(string line in File.ReadLines(Path.Combine(session,"log/shad_log.txt"),Encoding.UTF8)){var match=start.Match(line);if(match.Success)startup.Add(M("requested",match.Groups[1].Value=="true","supported",match.Groups[2].Value=="true","active",match.Groups[3].Value=="true"));match=compiled.Match(line);if(match.Success)compiles.Add(M("permutation",DiagnosticData.ParseInt(match.Groups[1].Value),"applied",match.Groups[2].Value=="true","reason",match.Groups[3].Value));}}catch(IOException error){issues.Add(error.Message);}
            string directory=Path.Combine(session,"user/shader/dumps");if(Directory.Exists(directory))foreach(string path in Directory.EnumerateFiles(directory,"cs_0x00000000ce1675e0_*.spv").OrderBy(value=>value,StringComparer.Ordinal)){
                try{var row=DepthSpirvFacts(File.ReadAllBytes(path));row["file"]=Path.GetFileName(path);binaries.Add(row);}catch(Exception error){if(!(error is IOException)&&!(error is InvalidDataException))throw;issues.Add(Path.GetFileName(path)+": "+error.Message);}
            }
            bool observed=binaries.Select(Json.Object).Any(row=>DiagnosticData.Flag(row,"candidate_pattern_observed"));return M("startup",startup,"compilations",compiles,"final_binaries",binaries,"mechanism_status",observed?"observed-final-binary":compiles.Select(Json.Object).Any(row=>DiagnosticData.Flag(row,"applied"))?"reported-compiled":compiles.Count>0?"fallback":"not-observed","issues",issues,"limits",new[]{"Final binary construction is not proof of dispatch, image correctness or FPS benefit.","IR dumps precede this C1 transform; inspect final SPIR-V for its operations.","Compilation logs can be absent when a shader is loaded from cache.","Unsupported/unmatched candidates fall back; this does not corrupt collected performance data."});
        }
        public static Dictionary<string,object> DescriptorSummary(string session,bool requireUpdates=false){using(var reader=new StreamReader(Path.Combine(session,"log/shad_log.txt"),Encoding.UTF8,true))return DescriptorSummary(reader,requireUpdates);}
        public static Dictionary<string,object> DescriptorSummary(TextReader reader,bool requireUpdates=false){
            var totals=M();var prepare=M();var updates=M();int reports=0,prepareReports=0,updateReports=0;var skews=new List<object>();var updateSkews=new List<object>();string line;
            while((line=reader.ReadLine())!=null){
                if(line.Contains("Perf R4 descriptors:")){var row=DescriptorLine(line);var residual=DescriptorInvariants(row);if(!Zero(residual)){residual["report"]=reports+1;skews.Add(residual);}foreach(var pair in row)Add(totals,pair.Key,Convert.ToInt64(pair.Value));reports++;}
                else if(line.Contains("Perf A1 descriptors:")){var row=UpdateLine(line);var residual=UpdateInvariants(row);if(!Zero(residual)){residual["report"]=updateReports+1;updateSkews.Add(residual);}foreach(var pair in row)Add(updates,pair.Key,Convert.ToInt64(pair.Value));updateReports++;}
                else if(line.Contains("Perf R4 prepare:")){var match=PreparePattern.Match(line);Check(match.Success,"malformed R4 preparation counters");string[] fields={"calls","prepare_ms","buffers","buffers_ms","textures","textures_ms","regular_sets","regular_writes"};for(int i=0;i<fields.Length;++i){double value=DiagnosticData.ParseNumber(match.Groups[i+1].Value);Check(value>=0&&DiagnosticData.Finite(value),"invalid R4 preparation counter");if(fields[i].EndsWith("_ms",StringComparison.Ordinal))prepare[fields[i]]=DiagnosticData.Number(DiagnosticData.Get(prepare,fields[i],0.0))+value;else Add(prepare,fields[i],checked((long)value));}prepareReports++;}
            }
            Check(reports>0&&prepareReports>0&&L(totals,"calls")>0,"R4 descriptor/preparation reports absent");Check(!requireUpdates||(updateReports>0&&L(updates,"calls")>0),"A1 descriptor update reports absent");object updateSummary=null;
            if(updateReports>0){var residual=UpdateInvariants(updates);updateSummary=M("reports",updateReports,"counts",updates,"snapshot_skew_intervals",updateSkews,"aggregate_invariants",residual,"aggregate_invariants_met",Zero(residual),"limits",new[]{"Omitted includes existing whole-call skips; partial_omitted isolates A1 subset omissions.","Counts measure write segments, not saved CPU time or normal FPS.","Independent atomic snapshots can have residuals; do not infer transport loss."});}
            var invariants=DescriptorInvariants(totals);return M("scope","All completed process log reporting intervals; NOT selected trace window.","reports",reports,"prepare_reports",prepareReports,"snapshot_skew_intervals",skews,"aggregate_invariants",invariants,"aggregate_invariants_met",Zero(invariants),"descriptors",totals,"preparation",prepare,"updates",updateSummary,"limits",new[]{"Segments are descriptor write segments, not unique binding numbers.","Field-change counts can overlap; do not add them as miss counts.","Prepare contains buffer/texture timers; do not sum nested times.","Hit means identical tracked snapshot, not necessarily a skipped API call.","Counters are sampled independently across threads; interval/aggregate residuals are reported, not proof of transport loss."});
        }
