                    if(queued!=null){Check(queued.Ns>=0&&(ulong)queued.Ns>=declared,"producer declaration occurred after its submission enqueue");DiagnosticData.AddCount(counts,"linked_enqueue");if(submit.ContainsKey("submit_driver_begin")&&submit.ContainsKey("submit_driver_end")){DiagnosticData.AddCount(counts,"linked_complete_submit");if((scopes&1)!=0&&recorded!=0&&(kind==3||kind==4))DiagnosticData.AddCount(counts,"request_compute_candidates_with_complete_submit");}Add(intervals,"declared_to_enqueue_cpu_ns",checked(queued.Ns-(long)declared));if(recorded!=0&&recorded<=(ulong)queued.Ns)Add(intervals,"recorded_to_enqueue_cpu_ns",checked(queued.Ns-(long)recorded));else if(recorded!=0)DiagnosticData.AddCount(counts,"cpu_command_return_after_enqueue");}
